			pass = b.Sub8(rt.Splat8(97)).LeU8(rt.Splat8(25)).Or(w.Sub8(rt.Splat8(48)).LeU8(rt.Splat8(9)).Or(w.Eq8(rt.Splat8(95)).Or(w.Eq8(rt.Splat8(36)))))
