// EmitCur is $emitCur.
func (m *Machine) EmitCur(t, lhs, rhs, next uint32) {
	var c, classify uint32
	if t == LexLBrace && rhs-lhs == 2 {
		m.Classify(m.PrevTok, t, next, lhs, rhs)
		m.TsrxEmitContainerOpen(lhs, rhs)
		return
	}
	if m.Mem[t+38800] != 253 {
		classify = m.Classify(m.PrevTok, t, next, lhs, rhs)
		m.EmitTok(classify, lhs, rhs)
		return
	}
	if t == LexStringLiteral {
		m.EmitEscaped(TokenString, lhs, rhs)
		return
	}
	if t == LexBacktick {
		m.EmitTemplate(lhs, rhs, false, true, true)
		return
	}
	if t == LexDollarBrace {
		m.EmitTemplate(lhs, rhs, true, true, false)
		return
	}
	if t == LexComment || t == LexHashBang {
		m.EmitTok(TokenComment, lhs, rhs)
		return
	}
	if t == LexMultilineComment {
		if m.IsDocComment(lhs, rhs) {
			m.EmitDocComment(lhs, rhs)
		} else {
			m.EmitTok(TokenComment, lhs, rhs)
		}
		return
	}
	if t == LexInvalid {
		c = uint32(m.Mem[lhs])
		if c == '"' || c == '\'' {
			m.EmitEscaped(TokenString, lhs, rhs)
			return
		}
		if c == '`' || c == '}' {
			m.EmitTemplate(lhs, rhs, false, true, false)
			return
		}
		if c == '/' {
			m.EmitTok(TokenStringRegex, lhs, rhs)
			return
		}
		m.EmitTok(TokenNone, lhs, rhs)
		return
	}
	m.EmitTok(TokenNone, lhs, rhs)
}

// TsxFinishStreamToken is $tsxFinishStreamToken.
