// TsxResume is $tsxResume.
func (m *Machine) TsxResume() bool {
	var t, quote uint32
	var c bool
	mode := m.TsxStreamMode
	if mode == 0 {
		return false
	}
	from := m.Ptr
	if mode&1 == 0 {
		quote = 34
	} else {
		quote = 39
	}
	if mode == 1 {
		t = m.ScanTemplateBody()
		m.EmitTemplate(from, m.Ptr, t == LexDollarBrace, false, t == LexBacktick)
		if t == LexInvalid {
			return true
		}
	} else {
		if mode <= 3 {
			m.ScanBlockCommentEnd()
			if mode == 3 {
				m.EmitDocCommentRange(from, m.Ptr, 0)
			} else {
				m.EmitTok(TokenComment, from, m.Ptr)
			}
			if m.Ptr-from < 2 || uint32(binary.LittleEndian.Uint16(m.Mem[m.Ptr-2:])) != 12074 {
				return true
			}
			m.TsxStreamMode = 0
			return false
		}
		if mode <= 5 {
			t = m.ScanStringBody(quote)
			m.EmitEscaped(TokenString, from, m.Ptr)
			if t == LexInvalid && m.Ptr == m.End {
				return true
			}
		} else {
			m.Ptr = m.ScanFind3(m.Ptr, quote, quote, quote)
			c = m.Ptr < m.End
			if c {
				m.Ptr++
			}
			m.EmitTok(TokenString, from, m.Ptr)
			if !c {
				return true
			}
			m.TsxStreamMode = 0
			return false
		}
	}
	m.TsxFinishStreamToken(t)
	m.TsxStreamMode = 0
	return false
}

// EcmaReset is $ecmaReset.
