// HlYaml is $hlYaml.
func (m *Machine) HlYaml() {
	var streamRoot, after, c, flow, hl, lhs, p, quote uint32
	var commentOk bool
	liveRoot := m.LiveEntering
	m.LiveEntering = false
	if m.LiveSuspended {
		m.LiveSuspended = false
		streamRoot = binary.LittleEndian.Uint32(m.Mem[98064:])
		flow = binary.LittleEndian.Uint32(m.Mem[98068:])
	} else {
		m.LexEmitLeadingContinuation()
		if m.Streaming && m.StreamDepth == 0 {
			m.StreamWindow = 46304
			streamRoot = 1
			m.StreamDepth = streamRoot
			if m.StreamReset == 0 {
				flow = binary.LittleEndian.Uint32(m.Mem[m.StreamWindow:])
			}
		}
	}
	for {
		if m.Ptr >= m.LiveLimit {
			if liveRoot {
				binary.LittleEndian.PutUint32(m.Mem[98064:], streamRoot)
				binary.LittleEndian.PutUint32(m.Mem[98068:], flow)
				m.LiveSuspended = true
				return
			}
		}
		lhs = m.Ptr
		m.ScanWhitespace()
		m.EmitGap(lhs, m.Ptr)
		if m.Ptr >= m.End {
			break
		}
		commentOk = m.Ptr != lhs || m.YamlAtLineStart(m.Ptr)
		lhs = m.Ptr
		c = uint32(m.Mem[m.Ptr])
		if c == '#' && commentOk {
			m.LexLineComment(1, TokenComment)
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			m.Ptr++
			for {
				m.Ptr = m.ScanFindSpecial(m.Ptr, m.End, quote, rt.B2u(quote == '"'), 0)
				if m.Ptr >= m.End {
					break
				}
				c = uint32(m.Mem[m.Ptr])
				m.Ptr++
				if c == '\'' && m.Ptr < m.End && m.Mem[m.Ptr] == '\'' {
					m.Ptr++
					continue
				}
				if c == quote {
					break
				}
				if m.Ptr < m.End {
					m.Ptr++
				}
			}
			after = m.YamlSkipHorizontal(m.Ptr)
			if after < m.End && m.Mem[after] == ':' {
				hl = TokenProperty
			} else {
				hl = TokenString
			}
			m.Ptr = lhs
			if quote == '"' {
				m.LexString(quote, true, hl)
			} else {
				for {
					m.LexRawString(quote, true, hl)
					if m.Ptr >= m.End {
						break
					}
					if m.Mem[m.Ptr] != '\'' {
						break
					}
					if m.Mem[m.Ptr-1] != '\'' {
						break
					}
				}
			}
			if hl == TokenProperty && m.Ptr <= after {
				m.EmitGap(m.Ptr, after)
				m.Ptr = after + 1
				m.EmitTok(TokenPunctuationDelimiter, after, m.Ptr)
			}
			continue
		}
		if c == '&' || c == '*' || c == '!' {
			m.Ptr++
			m.LexScanIdent()
			m.EmitTok(TokenType, lhs, m.Ptr)
			continue
		}
		if m.Ptr+3 <= m.End && (binary.LittleEndian.Uint32(m.Mem[m.Ptr:])&0xffffff == 0x2d2d2d || binary.LittleEndian.Uint32(m.Mem[m.Ptr:])&0xffffff == 0x2e2e2e) {
			m.Ptr += 3
			m.EmitTok(TokenPunctuationSpecial, lhs, m.Ptr)
			continue
		}
		if m.LexIsDigit(c) || ((c == '+' || c == '-') && m.Ptr+1 < m.End && m.LexIsDigit(uint32(m.Mem[m.Ptr+1]))) {
			if !m.LexIsDigit(c) {
				m.Ptr++
			}
			m.LexScanNumber()
			p = m.Ptr
			m.YamlScanPlain(flow)
			hl = TokenNumber
			if m.Ptr == p {
				if m.YamlColonEnds(m.YamlSkipHorizontal(m.Ptr), flow) {
					hl = TokenProperty
				}
				m.EmitTok(hl, lhs, m.Ptr)
				continue
			}
		} else {
			if m.Mem[c+1936]&1 != 0 {
				if uint32(m.Mem[c+1936])&2 != 0 {
					flow++
				} else if flow != 0 {
					flow--
				}
				m.Ptr++
				m.EmitTok(TokenPunctuationBracket, lhs, m.Ptr)
				continue
			}
			if c == '|' || c == '>' {
				if m.YamlBlockScalar() {
					continue
				}
			}
			if m.Mem[c+1936]&4 != 0 || m.YamlColonEnds(m.Ptr, flow) {
				m.Ptr++
				m.EmitTok(TokenPunctuationDelimiter, lhs, m.Ptr)
				continue
			}
		}
		m.YamlScanPlain(flow)
		if m.Ptr == lhs {
			m.Ptr++
		}
		hl = m.YamlWordHl(lhs, m.Ptr)
		if m.YamlColonEnds(m.YamlSkipHorizontal(m.Ptr), flow) {
			hl = TokenProperty
		}
		m.EmitTok(hl, lhs, m.Ptr)
	}
	if streamRoot != 0 {
		m.StreamWindow = 46304
		binary.LittleEndian.PutUint32(m.Mem[m.StreamWindow:], flow)
		if m.StreamStateLo > 80 {
			m.StreamStateLo = 80
		}
		if m.StreamStateHi < 84 {
			m.StreamStateHi = 84
		}
		m.StreamDepth = 0
	}
}

