// ApacheText is $apacheText.
func (m *Machine) ApacheText(rhs uint32) {
	var c, p uint32
	seg := m.Ptr
	for {
		if m.Ptr >= rhs {
			break
		}
		p = m.Ptr
		c = uint32(m.Mem[p])
		m.Ptr = p + 1
		if c != '%' && c != '$' {
			continue
		}
		c = uint32(m.Mem[m.Ptr])
		if m.Ptr < rhs && c == '{' {
			m.Ptr = m.ScanFindSpecial(m.Ptr, rhs, 125, 0, 0)
			if m.Ptr >= rhs {
				continue
			}
			m.Ptr++
		} else {
			if m.Ptr >= rhs || !m.LexIsDigit(c) {
				continue
			}
			m.Ptr++
			if m.Ptr < rhs && m.LexIsDigit(uint32(m.Mem[m.Ptr])) {
				continue
			}
		}
		m.EmitTok(TokenNone, seg, p)
		m.EmitTok(TokenVariable, p, m.Ptr)
		seg = m.Ptr
	}
	m.EmitTok(TokenNone, seg, m.Ptr)
}

// HlApache is $hlApache.
