// ApplescriptWord is $applescriptWord.
func (m *Machine) ApplescriptWord(n uint32) uint32 {
	if n > 7 {
		return 0xffffffff
	}
	w := binary.LittleEndian.Uint64(m.Mem[1360:]) & (uint64(1)<<(uint64(n<<3)&63) - 1)
	if w == 0x6572656877 || w == 0x65736f6877 {
		return TokenKeyword
	}
	if w == 0x6e616874 || w == 0x74276e7369 || w == 0x74276e73656f64 {
		return TokenKeywordOperator
	}
	return rt.Sel32(w == 0x746c75736572, TokenVariableSpecial, 0xffffffff)
}

