// PhpWordHl is $phpWordHl.
func (m *Machine) PhpWordHl(lhs, rhs uint32) uint32 {
	var w uint64
	var v rt.V128
	n := rhs - lhs
	if n-2 > 10 {
		return TokenVariable
	}
	switch n {
	case 2:
		w = binary.LittleEndian.Uint64(m.Mem[lhs:]) | 0x2020202020202020
		w &= 65535
		if w == 26217 || w == 28516 {
			return TokenKeywordControl
		}
		if w == 29537 || w == 28262 {
			return TokenKeyword
		}
		return TokenVariable
	case 3:
		w = binary.LittleEndian.Uint64(m.Mem[lhs:]) | 0x2020202020202020
		w &= 0xffffff
		if w == 0x77656e || w == 0x657375 || w == 0x726176 {
			return TokenKeyword
		}
		if w == 0x726f66 || w == 0x797274 {
			return TokenKeywordControl
		}
		if w == 0x746e69 {
			return TokenTypeBuiltin
		}
		return TokenVariable
	case 4:
		w = binary.LittleEndian.Uint64(m.Mem[lhs:]) | 0x2020202020202020
		w &= 0xffffffff
		if w == 0x65757274 {
			return TokenBoolean
		}
		if w == 0x6c6c756e {
			return TokenConstantBuiltin
		}
		if w == 0x65736c65 || w == 0x65736163 || w == 0x6f686365 || w == 0x6f746f67 {
			return TokenKeywordControl
		}
		if w == 0x6d756e65 {
			return TokenKeywordDeclaration
		}
		if w == 0x6c6f6f62 || w == 0x64696f76 {
			return TokenTypeBuiltin
		}
		return TokenVariable
	}
	v = rt.LdV(m.Mem[lhs:])
	rt.StV(m.Mem[1360:], v.Or(v.Sub8(rt.Splat8(65)).LeU8(rt.Splat8(25)).And(rt.Splat8(32))))
	hl := m.LexKeywordValue(1360, 1360+n, 24704, 15, 51)
	return rt.Sel32(int32(hl) >= 0, hl, TokenVariable)
}

// PhpAfterLine is $phpAfterLine.
