// ErbStreamResume is $erbStreamResume.
func (m *Machine) ErbStreamResume() bool {
	var tag uint32
	if m.StreamRegionKind == 27 {
		tag = m.StreamC
		if !m.ErbBody(tag) {
			return true
		}
		m.StreamRegionKind = 0
		m.StreamMode = 0
		m.StreamC = 0
		m.StreamClearCheckpoints()
		tag &= 0x3fffffff
		if tag != 0 {
			m.StreamDepth = 1
			m.ErbTagRest(tag)
			m.StreamDepth = 0
		}
		return m.Ptr >= m.End
	}
	save := m.End
	if m.StreamA == 0 {
		m.End = m.ErbNextCut(m.Ptr)
	}
	m.HTMLOpenTag = 0
	r := m.HTMLTagResume(26)
	m.End = save
	tag = m.HTMLOpenTag
	m.HTMLOpenTag = 0
	if tag != 0 && m.Ptr < m.End && m.ErbIsOpen(m.Ptr) {
		m.StreamDepth = 1
		if m.ErbTag(tag) {
			m.ErbTagRest(tag)
		}
		m.StreamDepth = 0
		r = m.Ptr >= m.End
	}
	return r
}

