	if c < 240 {
		return (c&15)<<12 | (m.LeanByte(p+1)&63)<<6 | m.LeanByte(p+2)&63
	}
	return (c&7)<<18 | (m.LeanByte(p+1)&63)<<12 | (m.LeanByte(p+2)&63)<<6 | m.LeanByte(p+3)&63
